import SwiftUI
struct GameHomeView: View {
 @Environment(LearningStore.self) private var store; @State private var learn=false; @State private var profile=false; @State private var chooser=false
 private let plans=MVPDemoData.plans
 var body:some View { NavigationStack { ZStack { LinearGradient(colors:[.indigo.opacity(0.2),.cyan.opacity(0.1),Color(.systemBackground)],startPoint:.topLeading,endPoint:.bottomTrailing).ignoresSafeArea(); ScrollView { VStack(spacing:14){top; dashboard; goals; launchPad}.padding(16) } }.toolbar{ToolbarItem(placement:.topBarTrailing){Button{profile=true}label:{Image(systemName:"gearshape.fill")}}}.sheet(isPresented:$learn){LearnSessionView()}.sheet(isPresented:$profile){NavigationStack{ProfileView()}}.sheet(isPresented:$chooser){MixChooserView(start:{qs in store.use(questions:qs);chooser=false;learn=true})} } }
 private var top:some View { HStack{VStack(alignment:.leading,spacing:2){Text("Уровень \(GameDemo.level)").font(.title.bold());Text("\(GameDemo.xp) / \(GameDemo.nextLevelXP) XP").font(.caption).foregroundStyle(.secondary)};ProgressView(value:Double(GameDemo.xp),total:Double(GameDemo.nextLevelXP));Label("\(GameDemo.streak)",systemImage:"flame.fill").foregroundStyle(.orange)} }
 private var dashboard:some View { HStack(spacing:10){stat("brain.head.profile","44%","освоено");stat("checkmark.circle.fill","32","вопроса");stat("clock.fill","24","мин");stat("bolt.fill","7","серия")}.padding(12).background(.ultraThinMaterial,in:RoundedRectangle(cornerRadius:22)) }
 private var goals:some View { VStack(alignment:.leading,spacing:9){Text("ЦЕЛИ").font(.caption.bold()).foregroundStyle(.secondary);goal("target","50 вопросов",32,50);goal("clock.fill","40 минут",24,40);goal("chart.line.uptrend.xyaxis","Освоить 70%",44,70);goal("flame.fill","10 дней подряд",4,10)} }
 private func goal(_ icon:String,_ title:String,_ value:Double,_ max:Double)->some View { HStack(spacing:10){Image(systemName:icon).frame(width:28).foregroundStyle(.indigo);Text(title).font(.subheadline.bold()).frame(width:120,alignment:.leading);ProgressView(value:value,total:max);Text("\(Int(value))/\(Int(max))").font(.caption.monospacedDigit()).foregroundStyle(.secondary).frame(width:45,alignment:.trailing)}.padding(.vertical,3) }
 private var launchPad:some View { VStack(spacing:10){Button{recommended()}label:{Label("ПРОДОЛЖИТЬ ПО РЕКОМЕНДАЦИИ",systemImage:"sparkles").frame(maxWidth:.infinity)}.buttonStyle(.borderedProminent).controlSize(.large);HStack{Button{chooser=true}label:{Label("Выбрать",systemImage:"square.grid.2x2").frame(maxWidth:.infinity)}.buttonStyle(.bordered);Button{random()}label:{Label("Случайно",systemImage:"shuffle").frame(maxWidth:.infinity)}.buttonStyle(.bordered)};Text("Можно выбрать один или несколько разделов и смешать вопросы").font(.caption).foregroundStyle(.secondary)}.padding(14).background(.thinMaterial,in:RoundedRectangle(cornerRadius:22)) }
 private func stat(_ icon:String,_ value:String,_ label:String)->some View { VStack(spacing:4){Image(systemName:icon).foregroundStyle(.indigo);Text(value).font(.headline.bold());Text(label).font(.caption2).foregroundStyle(.secondary)}.frame(maxWidth:.infinity) }
 private func recommended(){store.use(questions:MVPDemoData.questions(for:plans[0]));learn=true}; private func random(){let qs=plans.flatMap{MVPDemoData.questions(for:$0)}.shuffled();store.use(questions:Array(qs.prefix(15)));learn=true}
}

struct MixChooserView:View { let start:([StudyQuestion])->Void; @Environment(\.dismiss) private var dismiss; @State private var selected:Set<UUID>=Set(MVPDemoData.plans.map(\.id)); var body:some View{NavigationStack{VStack(spacing:16){List(MVPDemoData.plans){p in Button{if selected.contains(p.id){selected.remove(p.id)}else{selected.insert(p.id)}}label:{HStack{Image(systemName:selected.contains(p.id) ? "checkmark.circle.fill":"circle");VStack(alignment:.leading){Text(p.title);Text(p.subtitle).font(.caption).foregroundStyle(.secondary)}}}};Button("НАЧАТЬ СМЕШАННУЮ ТРЕНИРОВКУ"){let qs=MVPDemoData.plans.filter{selected.contains($0.id)}.flatMap{MVPDemoData.questions(for:$0)}.shuffled();start(Array(qs.prefix(20)))}.buttonStyle(.borderedProminent).controlSize(.large).disabled(selected.isEmpty).padding()}.navigationTitle("Что тренируем?").toolbar{ToolbarItem(placement:.cancellationAction){Button("Закрыть"){dismiss()}}}}} }
